//! Example art embedded in the binary and seeded into the data folder —
//! plan revision: "quando instalar o app, na pasta que ele cria colocar os
//! assets como exemplo nas pastas correspondentes".
//!
//! Each art slot (`assets/{cover,cartridge,backcover}` and `assets/manual`)
//! gets an `example.*`: the mocks generated by
//! `packaging/exemplo-mock/gerar-mocks.py`, which serve as the template
//! (size and shape of each slot) for the player's own art — and, in the
//! cartridge's case, a gray shell with no label ready for a new one. Never
//! overwrites: an existing file is the player's. (`assets/logo/` stays out
//! — without art the app already has its own default logo, and seeding
//! there would be noise.)
//!
//! File names on disk are always English, whatever the UI language ("as
//! pastas e arquivos no disco em inglês, sem opção") — `example.png` /
//! `example.pdf`, with a one-time rename of the old PT-named `exemplo.*`
//! seeds so a pre-existing install keeps its files.

use std::path::Path;

const COVER_PNG: &[u8] = include_bytes!("../assets/example-cover.png");
const CARTRIDGE_PNG: &[u8] = include_bytes!("../assets/example-cartridge.png");
const BACKCOVER_PNG: &[u8] = include_bytes!("../assets/example-backcover.png");
const MANUAL_PDF: &[u8] = include_bytes!("../assets/example-manual.pdf");

/// One art slot: relative path under `assets/` and the embedded mock.
const SLOTS: [(&str, &[u8]); 4] = [
    ("cover/example.png", COVER_PNG),
    ("cartridge/example.png", CARTRIDGE_PNG),
    ("backcover/example.png", BACKCOVER_PNG),
    ("manual/example.pdf", MANUAL_PDF),
];

/// Seeds the examples under `assets/` (folders created at startup, before
/// this call). Best-effort: a write failure logs and moves on. Before
/// seeding, renames the old PT-named `exemplo.*` seed of each slot — only
/// when the English name is free, so a file the player dropped there is
/// never touched.
pub fn seed(assets: &Path) {
    for (name, bytes) in SLOTS {
        migrate_legacy_name(assets, name);
        let alvo = assets.join(name);
        if alvo.is_file() {
            continue;
        }
        if let Some(pai) = alvo.parent() {
            let _ = std::fs::create_dir_all(pai);
        }
        match std::fs::write(&alvo, bytes) {
            Ok(()) => log::info!("example seeded: assets/{name}"),
            Err(e) => log::warn!("seeding assets/{name}: {e}"),
        }
    }
}

/// `cover/exemplo.png` → `cover/example.png` (same for the other slots) —
/// the disk names are English now, whatever the UI says. Only renames when
/// the target doesn't exist: both present means the target is either the
/// fresh seed or already the player's file, and the old one never gets
/// deleted (it may hold the player's art). Idempotent.
fn migrate_legacy_name(assets: &Path, name: &str) {
    let new = assets.join(name);
    if new.exists() {
        return;
    }
    let Some(file_name) = Path::new(name).file_name().and_then(|n| n.to_str()) else {
        return;
    };
    let legacy = new.with_file_name(file_name.replacen("example", "exemplo", 1));
    if !legacy.is_file() {
        return;
    }
    match std::fs::rename(&legacy, &new) {
        Ok(()) => log::info!(
            "migrated: assets/{} -> {}",
            legacy.strip_prefix(assets).unwrap_or(&legacy).display(),
            name
        ),
        Err(e) => log::warn!("migrating assets/{name}: {e}"),
    }
}

#[cfg(test)]
mod tests {
    use std::fs;

    fn test_assets_dir(label: &str) -> std::path::PathBuf {
        let tmp =
            std::env::temp_dir().join(format!("sixteen-example-{label}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&tmp);
        fs::create_dir_all(&tmp).unwrap();
        tmp
    }

    #[test]
    fn seeds_one_example_in_each_art_folder() {
        let assets = test_assets_dir("seed");
        super::seed(&assets);

        for name in [
            "cover/example.png",
            "cartridge/example.png",
            "backcover/example.png",
            "manual/example.pdf",
        ] {
            let file = assets.join(name);
            assert!(file.is_file(), "missing {name}");
            assert!(fs::metadata(&file).unwrap().len() > 0, "{name} empty");
            assert!(!assets.join(name.replace("example", "exemplo")).exists());
        }
        // The logo isn't seeded — the app already has its own default.
        assert!(!assets.join("logo/example.png").exists());

        // The player's file wins: swapped-in content doesn't turn back
        // into the mock.
        fs::write(assets.join("cover/example.png"), b"player art").unwrap();
        super::seed(&assets);
        assert_eq!(
            fs::read(assets.join("cover/example.png")).unwrap(),
            b"player art"
        );

        let _ = fs::remove_dir_all(&assets);
    }

    #[test]
    fn seeds_even_without_the_art_folders() {
        // Startup creates the folders before seeding, but the function
        // shouldn't depend on that (data folder wiped mid-run, standalone
        // call).
        let assets = test_assets_dir("no-folders");
        super::seed(&assets);
        assert!(assets.join("manual/example.pdf").is_file());
        let _ = fs::remove_dir_all(&assets);
    }

    #[test]
    fn legacy_pt_named_seeds_rename_once() {
        let assets = test_assets_dir("migrate");
        // A pre-rename install: old seed in place, no folder surprises.
        for name in [
            "cover/exemplo.png",
            "cartridge/exemplo.png",
            "backcover/exemplo.png",
            "manual/exemplo.pdf",
        ] {
            fs::create_dir_all(assets.join(name).parent().unwrap()).unwrap();
            fs::write(assets.join(name), b"old seed").unwrap();
        }
        super::seed(&assets);
        for name in [
            "cover/example.png",
            "cartridge/example.png",
            "backcover/example.png",
            "manual/example.pdf",
        ] {
            assert!(assets.join(name).is_file(), "{name} after migrate");
            assert!(!assets.join(name.replace("example", "exemplo")).exists());
        }
        // The renamed file is the OLD one (player content rides along),
        // not the fresh mock.
        assert_eq!(
            fs::read(assets.join("cover/example.png")).unwrap(),
            b"old seed"
        );

        // Both present (player already made an example.png): the old file
        // stays — never deleted, it may hold player art — and the seed
        // doesn't overwrite the player's file either.
        fs::write(assets.join("cover/exemplo.png"), b"old again").unwrap();
        super::seed(&assets);
        assert_eq!(
            fs::read(assets.join("cover/example.png")).unwrap(),
            b"old seed"
        );
        assert_eq!(
            fs::read(assets.join("cover/exemplo.png")).unwrap(),
            b"old again"
        );

        let _ = fs::remove_dir_all(&assets);
    }
}
